.form-grid h3 { margin: 14px 0 4px; font-size: 13px; text-transform: uppercase; letter-spacing: .6px; color: var(--text-2); border-top: 1px solid var(--line); padding-top: 14px; }
.ship-card .ship-top { display: flex; justify-content: space-between; align-items: flex-start; gap: 12px; flex-wrap: wrap; }
.ship-now { display: flex; align-items: center; gap: 8px; margin: 2px 0 0; font-size: 19px; color: var(--navy); }
.ship-now .ic { width: 22px; height: 22px; color: var(--brand); flex: none; }
.ship-now.warn, .ship-now.warn .ic { color: var(--warn); }
.ship-badges { display: flex; gap: 6px; flex-wrap: wrap; }
.route { list-style: none; margin: 18px 0 8px; padding: 0; display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); position: relative; }
.route::before { content: ""; position: absolute; left: calc(100% / 6); right: calc(100% / 6); top: 17px; height: 3px; border-radius: 3px; background: var(--line); }
.route li { position: relative; display: flex; flex-direction: column; align-items: center; text-align: center; gap: 2px; padding: 0 6px; min-width: 0; }
.route li b { font-size: 13.5px; overflow-wrap: anywhere; }
.route li small { color: var(--muted); font-size: 12px; overflow-wrap: anywhere; }
.r-dot { position: relative; z-index: 1; display: grid; place-items: center; width: 36px; height: 36px; border-radius: 50%; background: var(--surface); border: 2px solid var(--line-2); color: var(--muted); margin-bottom: 4px; }
.r-dot .ic { width: 18px; height: 18px; }
.route li.done .r-dot { border-color: var(--ok); color: var(--ok); background: var(--ok-soft); }
.route li.now .r-dot { border-color: var(--brand); color: #fff; background: var(--brand); box-shadow: 0 0 0 5px var(--brand-soft); }
.route li.now.warn .r-dot { border-color: var(--warn); background: var(--warn); box-shadow: 0 0 0 5px var(--warn-soft); }
.route li.now.done .r-dot { border-color: var(--ok); background: var(--ok); color: #fff; box-shadow: 0 0 0 5px var(--ok-soft); }
.ship-info { margin-top: 10px; }
.ship-info h3 { margin: 0 0 8px; font-size: 12.5px; text-transform: uppercase; letter-spacing: .6px; color: var(--muted); }
.goods { list-style: none; margin: 0 0 10px; padding: 0; }
.goods li { padding: 6px 10px; border: 1px solid var(--line); border-radius: 10px; margin-bottom: 6px; background: var(--surface-2); }
.goods-edit { display: flex; flex-direction: column; gap: 6px; align-items: flex-start; }
.goods-row { display: grid; grid-template-columns: minmax(0, 1fr) 80px 30px; gap: 8px; align-items: center; width: 100%; }
.goods-row input { margin: 0; }

#excel { margin-bottom: 18px; }

/* ---------- X, l'assistant IA ---------- */
.x-logo { display: inline-grid; place-items: center; flex: none; width: 40px; height: 40px; border-radius: 12px; font: 900 22px/1 var(--font); color: #fff;
  background: linear-gradient(135deg, #0a1f4d 0%, #1f7bff 60%, #46c2ff 100%); box-shadow: 0 4px 14px rgba(31, 123, 255, .3); }
.x-logo.sm { width: 28px; height: 28px; border-radius: 9px; font-size: 15px; }
.x-logo.lg { width: 64px; height: 64px; border-radius: 18px; font-size: 34px; }
.x-setup { max-width: 640px; margin: 24px auto; text-align: center; }
.x-setup p { color: var(--text-2); }
.x-chat { display: flex; flex-direction: column; min-height: calc(100vh - 150px); max-width: 980px; margin: 0 auto; }
.x-head { display: flex; gap: 12px; align-items: center; padding-bottom: 12px; border-bottom: 1px solid var(--line); }
.x-head h2 { margin: 0; }
.x-head p { margin: 2px 0 0; }
.x-head .grow { flex: 1; min-width: 0; }
.x-log { flex: 1; overflow-y: auto; padding: 16px 2px; display: flex; flex-direction: column; gap: 14px; min-height: 260px; max-height: calc(100vh - 330px); }
.x-empty { margin: auto 0; }
.x-sugg { display: flex; flex-wrap: wrap; gap: 8px; }
.x-sugg .chip { cursor: pointer; font: inherit; font-size: 13px; text-align: left; }
.x-msg { display: flex; gap: 10px; align-items: flex-start; }
.x-msg.user { justify-content: flex-end; }
.x-msg.user .x-bubble { background: var(--navy); color: #fff; border-radius: 16px 16px 4px 16px; padding: 10px 14px; max-width: 75%; overflow-wrap: anywhere; }
.x-msg.bot .x-bubble { flex: 1; min-width: 0; padding: 2px 0; }
.x-text { line-height: 1.55; }
.x-text p { margin: 0 0 10px; }
.x-text h3, .x-text h4, .x-text h5, .x-text h6 { margin: 12px 0 6px; font-size: 15px; }
.x-text ul, .x-text ol { margin: 0 0 10px; padding-left: 22px; }
.x-text code { background: var(--surface-2); border: 1px solid var(--line); border-radius: 6px; padding: 0 4px; font-size: 12.5px; }
.x-text pre { background: var(--surface-2); border: 1px solid var(--line); border-radius: 10px; padding: 10px; overflow-x: auto; }
.x-table { overflow-x: auto; margin: 4px 0 12px; border: 1px solid var(--line); border-radius: 10px; }
.x-table .tbl { margin: 0; }
.x-table .tbl th, .x-table .tbl td { padding: 7px 10px; }
.x-step { font-size: 12.5px; color: var(--muted); margin: 0 0 6px; }
.x-step summary { cursor: pointer; display: flex; align-items: center; gap: 8px; list-style: none; }
.x-step summary::-webkit-details-marker { display: none; }
.x-step summary small { color: var(--muted); }
.x-step pre { margin: 6px 0 4px; padding: 8px 10px; background: var(--surface-2); border: 1px solid var(--line); border-radius: 8px; white-space: pre-wrap; font-size: 12px; color: var(--text-2); }
.x-step.err summary { color: var(--err); }
.x-tick { display: inline-grid; place-items: center; width: 16px; height: 16px; border-radius: 50%; background: var(--ok-soft); color: var(--ok); font-size: 11px; font-weight: 700; }
.x-step.err .x-tick { background: var(--err-soft); color: var(--err); }
.x-spin { width: 14px; height: 14px; border-radius: 50%; border: 2px solid var(--line-2); border-top-color: var(--brand); animation: x-spin .8s linear infinite; }
@keyframes x-spin { to { transform: rotate(360deg); } }
.x-typing { display: inline-flex; gap: 4px; padding: 8px 0; }
.x-typing i { width: 7px; height: 7px; border-radius: 50%; background: var(--line-2); animation: x-dot 1.2s infinite ease-in-out; }
.x-typing i:nth-child(2) { animation-delay: .15s; }
.x-typing i:nth-child(3) { animation-delay: .3s; }
@keyframes x-dot { 0%, 80%, 100% { opacity: .35; transform: translateY(0); } 40% { opacity: 1; transform: translateY(-3px); background: var(--brand); } }
.x-note { margin: 4px 0 8px; padding: 8px 12px; border-radius: 10px; background: var(--surface-2); color: var(--text-2); font-size: 13px; }
.x-note.err { background: var(--err-soft); color: var(--err); }
.x-note.warn { background: var(--warn-soft); color: var(--warn); }
.x-form { display: flex; gap: 10px; align-items: flex-end; padding-top: 12px; border-top: 1px solid var(--line); }
.x-form textarea { flex: 1; resize: vertical; min-height: 46px; max-height: 200px; margin: 0; }
.x-ask { display: flex; gap: 10px; align-items: center; padding: 8px 8px 8px 12px; margin: 0 0 16px; background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius); box-shadow: var(--shadow); }
.x-ask input { flex: 1; margin: 0; border: 0; box-shadow: none; background: transparent; min-width: 0; }
.x-ask input:focus { outline: none; }
.x-ask:focus-within { border-color: var(--brand); box-shadow: 0 0 0 3px var(--brand-soft); }

@media (max-width: 700px) {
  .route { grid-template-columns: 1fr; gap: 10px; }
  .route::before { left: 17px; right: auto; top: 18px; bottom: 18px; width: 3px; height: auto; }
  .route li { flex-direction: row; flex-wrap: wrap; text-align: left; align-items: center; gap: 2px 10px; padding: 0; }
  .x-msg.user .x-bubble { max-width: 88%; }
  .x-log { max-height: none; }
  .x-chat { min-height: calc(100vh - 190px); }
  .x-form .btn span { display: none; }
  .goods-row { grid-template-columns: minmax(0, 1fr) 64px 30px; }
}

